// File Name      : twiddle_rom.sv
// Author         : Mostafa Ihab
// Creation Date  : 2026-09-28
// Version        : 1.0
// Description    : 16-entry combinational Twiddle Factor ROM storing W_32^k
//                  in 16-bit signed Q1.15 fixed-point format.
//                  Auto-generated by scripts/generate_twiddles.py.
//                  Includes zero-power hardware bypass flags (is_unity, is_neg_j).
// =============================================================================

import fft_pkg::*;

module twiddle_rom #(
    parameter int N          = 32,
    parameter int ADDR_WIDTH = 4
)(
    input  logic [ADDR_WIDTH-1:0] addr,
    output complex_t              twiddle,
    output logic                  is_unity,
    output logic                  is_neg_j
);

    assign is_unity = (addr == '0);
    assign is_neg_j = (addr == 4'd8);

    always_comb begin
        case (addr)
            4'd0: begin twiddle.re = 16'sh7FFF; twiddle.im = 16'sh0000; end // W32^0: cos= 1.0000, sin= 0.0000
            4'd1: begin twiddle.re = 16'sh7D8A; twiddle.im = 16'shE707; end // W32^1: cos= 0.9808, sin=-0.1951
            4'd2: begin twiddle.re = 16'sh7642; twiddle.im = 16'shCF04; end // W32^2: cos= 0.9239, sin=-0.3827
            4'd3: begin twiddle.re = 16'sh6A6E; twiddle.im = 16'shB8E3; end // W32^3: cos= 0.8315, sin=-0.5556
            4'd4: begin twiddle.re = 16'sh5A82; twiddle.im = 16'shA57E; end // W32^4: cos= 0.7071, sin=-0.7071
            4'd5: begin twiddle.re = 16'sh471D; twiddle.im = 16'sh9592; end // W32^5: cos= 0.5556, sin=-0.8315
            4'd6: begin twiddle.re = 16'sh30FC; twiddle.im = 16'sh89BE; end // W32^6: cos= 0.3827, sin=-0.9239
            4'd7: begin twiddle.re = 16'sh18F9; twiddle.im = 16'sh8276; end // W32^7: cos= 0.1951, sin=-0.9808
            4'd8: begin twiddle.re = 16'sh0000; twiddle.im = 16'sh8000; end // W32^8: cos= 0.0000, sin=-1.0000
            4'd9: begin twiddle.re = 16'shE707; twiddle.im = 16'sh8276; end // W32^9: cos=-0.1951, sin=-0.9808
            4'd10: begin twiddle.re = 16'shCF04; twiddle.im = 16'sh89BE; end // W32^10: cos=-0.3827, sin=-0.9239
            4'd11: begin twiddle.re = 16'shB8E3; twiddle.im = 16'sh9592; end // W32^11: cos=-0.5556, sin=-0.8315
            4'd12: begin twiddle.re = 16'shA57E; twiddle.im = 16'shA57E; end // W32^12: cos=-0.7071, sin=-0.7071
            4'd13: begin twiddle.re = 16'sh9592; twiddle.im = 16'shB8E3; end // W32^13: cos=-0.8315, sin=-0.5556
            4'd14: begin twiddle.re = 16'sh89BE; twiddle.im = 16'shCF04; end // W32^14: cos=-0.9239, sin=-0.3827
            4'd15: begin twiddle.re = 16'sh8276; twiddle.im = 16'shE707; end // W32^15: cos=-0.9808, sin=-0.1951
            default: begin twiddle.re = 16'sh7FFF; twiddle.im = 16'sh0000; end
        endcase
    end

endmodule : twiddle_rom
